BEGIN READ ONLY;
SELECT jsonb_build_object(
'observedAt',now(),'readOnly',current_setting('transaction_read_only'),
'publicTableRolePrivileges',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'role',r,'select',has_table_privilege(r,c.oid,'SELECT'),'dml',has_table_privilege(r,c.oid,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER,MAINTAIN'),'columnSelect',has_any_column_privilege(r,c.oid,'SELECT'),'columnDml',has_any_column_privilege(r,c.oid,'INSERT,UPDATE,REFERENCES')) ORDER BY c.relname,r) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN unnest(ARRAY['anon','authenticated','service_role'])r WHERE n.nspname='public' AND c.relkind='r'),
'schemaPrivileges',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'role',r,'owner',pg_get_userbyid(n.nspowner),'usage',has_schema_privilege(r,n.oid,'USAGE'),'create',has_schema_privilege(r,n.oid,'CREATE')) ORDER BY n.nspname,r) FROM pg_namespace n CROSS JOIN unnest(ARRAY['anon','authenticated','service_role'])r WHERE n.nspname='public' OR left(n.nspname,5)='busy_'),
'sequencePrivileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'role',r,'access',has_sequence_privilege(r,c.oid,'USAGE,SELECT,UPDATE')) ORDER BY n.nspname,c.relname,r),'[]') FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace CROSS JOIN unnest(ARRAY['anon','authenticated','service_role'])r WHERE c.relkind='S' AND(n.nspname='public' OR left(n.nspname,5)='busy_')),
'privateFunctions',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',n.nspname,'signature',p.oid::regprocedure::text,'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'anon',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service',has_function_privilege('service_role',p.oid,'EXECUTE')) ORDER BY n.nspname,p.proname),'[]') FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE left(n.nspname,5)='busy_'),
'nativeHookRolePrivileges',(SELECT jsonb_agg(jsonb_build_object('role',r,'execute',has_function_privilege(r,'public.rls_auto_enable()','EXECUTE'))) FROM unnest(ARRAY['anon','authenticated','service_role','postgres'])r),
'defaultPrivileges',(SELECT coalesce(jsonb_agg(jsonb_build_object('owner',pg_get_userbyid(d.defaclrole),'schema',CASE WHEN d.defaclnamespace=0 THEN 'GLOBAL' ELSE n.nspname END,'kind',d.defaclobjtype::text,'acl',d.defaclacl::text) ORDER BY d.defaclrole,d.defaclnamespace,d.defaclobjtype),'[]') FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclrole='postgres'::regrole),
'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'roles',roles,'cmd',cmd,'permissive',permissive,'qual',qual,'withCheck',with_check) ORDER BY schemaname,tablename,policyname),'[]') FROM pg_policies WHERE schemaname='public' OR left(schemaname,5)='busy_'),
'publicRowCounts',(SELECT jsonb_agg(to_jsonb(x) ORDER BY name) FROM (SELECT 'business_work_agreement_decisions' AS name,count(*) AS rows FROM public.business_work_agreement_decisions UNION ALL SELECT 'business_work_agreement_evidence' AS name,count(*) AS rows FROM public.business_work_agreement_evidence UNION ALL SELECT 'business_work_engagements' AS name,count(*) AS rows FROM public.business_work_engagements UNION ALL SELECT 'business_work_private_drafts' AS name,count(*) AS rows FROM public.business_work_private_drafts UNION ALL SELECT 'business_work_quote_recipient_bindings' AS name,count(*) AS rows FROM public.business_work_quote_recipient_bindings UNION ALL SELECT 'business_work_quote_references' AS name,count(*) AS rows FROM public.business_work_quote_references UNION ALL SELECT 'busy_business_content' AS name,count(*) AS rows FROM public.busy_business_content UNION ALL SELECT 'busy_business_memberships' AS name,count(*) AS rows FROM public.busy_business_memberships UNION ALL SELECT 'busy_business_snapshots' AS name,count(*) AS rows FROM public.busy_business_snapshots UNION ALL SELECT 'busy_businesses' AS name,count(*) AS rows FROM public.busy_businesses UNION ALL SELECT 'busy_creator_draft_heads' AS name,count(*) AS rows FROM public.busy_creator_draft_heads UNION ALL SELECT 'busy_creator_draft_versions' AS name,count(*) AS rows FROM public.busy_creator_draft_versions UNION ALL SELECT 'busy_growth_opportunities' AS name,count(*) AS rows FROM public.busy_growth_opportunities UNION ALL SELECT 'busy_growth_opportunity_versions' AS name,count(*) AS rows FROM public.busy_growth_opportunity_versions UNION ALL SELECT 'busy_mini_app_entry_daily' AS name,count(*) AS rows FROM public.busy_mini_app_entry_daily UNION ALL SELECT 'busy_mini_app_entry_events' AS name,count(*) AS rows FROM public.busy_mini_app_entry_events UNION ALL SELECT 'busy_mini_app_message_delivery_outbox' AS name,count(*) AS rows FROM public.busy_mini_app_message_delivery_outbox UNION ALL SELECT 'busy_mini_app_module_catalog' AS name,count(*) AS rows FROM public.busy_mini_app_module_catalog UNION ALL SELECT 'busy_mini_app_request_links' AS name,count(*) AS rows FROM public.busy_mini_app_request_links UNION ALL SELECT 'busy_mini_app_request_messages' AS name,count(*) AS rows FROM public.busy_mini_app_request_messages UNION ALL SELECT 'busy_mini_app_requests' AS name,count(*) AS rows FROM public.busy_mini_app_requests UNION ALL SELECT 'busy_mini_app_versions' AS name,count(*) AS rows FROM public.busy_mini_app_versions UNION ALL SELECT 'busy_mini_app_work_bookings' AS name,count(*) AS rows FROM public.busy_mini_app_work_bookings UNION ALL SELECT 'busy_mini_apps' AS name,count(*) AS rows FROM public.busy_mini_apps UNION ALL SELECT 'busy_public_business_profiles' AS name,count(*) AS rows FROM public.busy_public_business_profiles UNION ALL SELECT 'busy_push_deliveries' AS name,count(*) AS rows FROM public.busy_push_deliveries UNION ALL SELECT 'busy_website_deployments' AS name,count(*) AS rows FROM public.busy_website_deployments UNION ALL SELECT 'busy_websites' AS name,count(*) AS rows FROM public.busy_websites)x),
'moduleCatalog',(SELECT jsonb_agg(jsonb_build_object('module',module_key,'version',module_version,'status',status) ORDER BY module_key) FROM public.busy_mini_app_module_catalog),
'policyRows',(SELECT count(*) FROM busy_ai_private.policy),
'extensions',(SELECT jsonb_agg(jsonb_build_object('name',extname,'version',extversion,'schema',n.nspname) ORDER BY extname) FROM pg_extension e JOIN pg_namespace n ON n.oid=e.extnamespace),
'eventTriggers',(SELECT jsonb_agg(jsonb_build_object('name',evtname,'owner',pg_get_userbyid(evtowner),'enabled',evtenabled::text,'function',evtfoid::regprocedure::text,'tags',evttags) ORDER BY evtname) FROM pg_event_trigger)
) AS security_verification;
COMMIT;
